// Package uuid implements the uuid template-function namespace: functions
// for generating, parsing, and manipulating RFC 4122 UUIDs.
//
// The UUID type and its helpers mirror the behaviour of the reference tool,
// which exposes a google/uuid-style UUID value to templates. Only the Go
// standard library is used.
package uuid

import (
	"crypto/rand"
	"encoding/binary"
	"errors"
	"fmt"
	"io"
	"net"
	"strconv"
	"strings"
	"sync"
	"time"
)

// UUID is a 128 bit (16 byte) Universal Unique IDentifier as defined in
// RFC 4122.
type UUID [16]byte

// Nil is the nil UUID, i.e. all zeros.
var Nil UUID

// Version is the version of a UUID (the high nibble of the 7th byte).
type Version byte

// Variant is the variant of a UUID.
type Variant byte

// Domain is the "domain" of a version 2 UUID (the 10th byte).
type Domain byte

// Time is the number of 100-nanosecond intervals since 00:00:00.00,
// 15 October 1582 (the epoch of the Gregorian calendar reform).
type Time int64

// UUID variants, as defined by RFC 4122.
const (
	VariantNCS Variant = iota
	VariantRFC4122
	VariantMicrosoft
	VariantFuture
	VariantReserved
)

// Funcs is the uuid namespace. Its methods are the template functions.
type Funcs struct{}

// NS returns the uuid namespace value for use in a template FuncMap.
func NS() any {
	return &Funcs{}
}

// V1 creates a version 1 UUID (based on the current MAC address and the
// current date/time).
func (Funcs) V1() (string, error) {
	u, err := newV1()
	if err != nil {
		return "", err
	}
	return u.String(), nil
}

// V4 creates a version 4 UUID (randomly generated). This function consumes
// entropy.
func (Funcs) V4() (string, error) {
	u, err := newV4()
	if err != nil {
		return "", err
	}
	return u.String(), nil
}

// Nil returns the nil UUID, mostly for testing scenarios.
func (Funcs) Nil() string {
	return Nil.String()
}

// IsValid checks that the given UUID is in the correct format. It does not
// validate whether the version or variant are correct.
func (Funcs) IsValid(u any) bool {
	_, err := Parse(toString(u))
	return err == nil
}

// Parse parses a UUID for further manipulation or inspection. Both the
// standard forms "xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx" and
// "urn:uuid:xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx" are decoded, as well as
// the Microsoft encoding "{xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx}" and the
// raw hex encoding ("xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx").
func (Funcs) Parse(u any) (UUID, error) {
	return Parse(toString(u))
}

// toString converts a template data value to a string, matching the
// reference tool's coercion semantics: nil becomes "nil", strings pass
// through, floats are formatted without scientific notation, and everything
// else uses fmt's default formatting.
func toString(in any) string {
	if in == nil {
		return "nil"
	}
	if s, ok := in.(string); ok {
		return s
	}
	if s, ok := in.(fmt.Stringer); ok {
		return s.String()
	}
	switch f := in.(type) {
	case float64:
		return strconv.FormatFloat(f, 'f', -1, 64)
	case float32:
		return strconv.FormatFloat(f, 'f', -1, 32)
	}
	return fmt.Sprintf("%v", in)
}

// Parse decodes s into a UUID or returns an error. See Funcs.Parse for the
// accepted formats.
func Parse(s string) (UUID, error) {
	var uuid UUID
	switch len(s) {
	// xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx
	case 36:

	// urn:uuid:xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx
	case 36 + 9:
		if !strings.EqualFold(s[:9], "urn:uuid:") {
			return uuid, fmt.Errorf("invalid urn prefix: %q", s[:9])
		}
		s = s[9:]

	// {xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx}
	case 36 + 2:
		s = s[1:]

	// xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx
	case 32:
		var ok bool
		for i := range uuid {
			uuid[i], ok = xtob(s[i*2], s[i*2+1])
			if !ok {
				return uuid, errors.New("invalid UUID format")
			}
		}
		return uuid, nil

	default:
		return uuid, fmt.Errorf("invalid UUID length: %d", len(s))
	}

	// s is now at least 36 bytes long
	// it must be of the form  xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx
	if s[8] != '-' || s[13] != '-' || s[18] != '-' || s[23] != '-' {
		return uuid, errors.New("invalid UUID format")
	}
	for i, x := range [16]int{
		0, 2, 4, 6,
		9, 11,
		14, 16,
		19, 21,
		24, 26, 28, 30, 32, 34,
	} {
		v, ok := xtob(s[x], s[x+1])
		if !ok {
			return uuid, errors.New("invalid UUID format")
		}
		uuid[i] = v
	}
	return uuid, nil
}

