// xtob converts hex characters x1 and x2 into a byte.
func xtob(x1, x2 byte) (byte, bool) {
	b1, b2 := xvalues[x1], xvalues[x2]
	return (b1 << 4) | b2, b1 != 255 && b2 != 255
}

const hexDigits = "0123456789abcdef"

// encodeCanonical encodes uuid as "xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx"
// into dst (at least 36 bytes).
func encodeCanonical(dst []byte, uuid UUID) {
	for i, x := range [16]int{
		0, 2, 4, 6,
		9, 11,
		14, 16,
		19, 21,
		24, 26, 28, 30, 32, 34,
	} {
		dst[x] = hexDigits[uuid[i]>>4]
		dst[x+1] = hexDigits[uuid[i]&0x0f]
	}
	dst[8] = '-'
	dst[13] = '-'
	dst[18] = '-'
	dst[23] = '-'
}

// String returns the canonical string form of uuid:
// xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx.
func (uuid UUID) String() string {
	var buf [36]byte
	encodeCanonical(buf[:], uuid)
	return string(buf[:])
}

// URN returns the RFC 2141 URN form of uuid,
// urn:uuid:xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx.
func (uuid UUID) URN() string {
	var buf [36 + 9]byte
	copy(buf[:], "urn:uuid:")
	encodeCanonical(buf[9:], uuid)
	return string(buf[:])
}

// Variant returns the variant encoded in uuid.
func (uuid UUID) Variant() Variant {
	switch {
	case (uuid[8] & 0xc0) == 0x80:
		return VariantRFC4122
	case (uuid[8] & 0xe0) == 0xc0:
		return VariantMicrosoft
	case (uuid[8] & 0xe0) == 0xe0:
		return VariantFuture
	default:
		return VariantReserved
	}
}

// String returns the name of the variant.
func (v Variant) String() string {
	switch v {
	case VariantRFC4122:
		return "RFC4122"
	case VariantMicrosoft:
		return "Microsoft"
	case VariantFuture:
		return "Future"
	case VariantReserved:
		return "Reserved"
	case VariantNCS:
		return "VariantNCS"
	default:
		return fmt.Sprintf("BadVariant%d", int(v))
	}
}

// Version returns the version of uuid.
func (uuid UUID) Version() Version {
	return Version(uuid[6] >> 4)
}

// String returns the name of the version, e.g. "VERSION_4".
func (v Version) String() string {
	if v > 15 {
		return fmt.Sprintf("BAD_VERSION_%d", v)
	}
	return fmt.Sprintf("VERSION_%d", v)
}

// Domain returns the domain of uuid.
func (uuid UUID) Domain() Domain {
	return Domain(uuid[9])
}

// String returns the name of the domain: Person, Group, Org, or "Domain%d".
func (d Domain) String() string {
	switch d {
	case 0:
		return "Person"
	case 1:
		return "Group"
	case 2:
		return "Org"
	default:
		return fmt.Sprintf("Domain%d", int(d))
	}
}

// Time returns the time in 100s of nanoseconds since 15 Oct 1582 encoded in
// uuid. The time is only defined for version 1 and 2 UUIDs.
func (uuid UUID) Time() Time {
	t := int64(binary.BigEndian.Uint32(uuid[0:4]))
	t |= int64(binary.BigEndian.Uint16(uuid[4:6])) << 32
	t |= int64(binary.BigEndian.Uint16(uuid[6:8])&0xfff) << 48
	return Time(t)
}

// UnixTime returns the seconds and nanoseconds since the Unix epoch
// encoded in t.
func (t Time) UnixTime() (sec, nsec int64) {
	sec = int64(t)/10000000 - 12219292800
	nsec = (int64(t) - (sec+12219292800)*10000000) * 100
	return sec, nsec
}

// ClockSequence returns the clock sequence encoded in uuid.
func (uuid UUID) ClockSequence() int {
	return int(binary.BigEndian.Uint16(uuid[8:10]) & 0x3fff)
}

// ID returns the id (the first 4 bytes of uuid) as a uint32. Only meaningful
// for version 2 UUIDs.
func (uuid UUID) ID() uint32 {
	return binary.BigEndian.Uint32(uuid[0:4])
}

// NodeID returns the 6 byte node id encoded in uuid. It returns nil if the
// node id is not valid (i.e. the multicast bit is not set).
func (uuid UUID) NodeID() []byte {
	var node [6]byte
	copy(node[:], uuid[10:])
	return node[:]
}

// MarshalText implements encoding.TextMarshaler.
func (uuid UUID) MarshalText() ([]byte, error) {
	var buf [36]byte
	encodeCanonical(buf[:], uuid)
	return buf[:], nil
}

// UnmarshalText implements encoding.TextUnmarshaler.
func (uuid *UUID) UnmarshalText(data []byte) error {
	id, err := Parse(string(data))
	if err != nil {
		return err
	}
	*uuid = id
	return nil
}

// MarshalBinary implements encoding.BinaryMarshaler.
func (uuid UUID) MarshalBinary() ([]byte, error) {
	return uuid[:], nil
}

// UnmarshalBinary implements encoding.BinaryUnmarshaler.
func (uuid *UUID) UnmarshalBinary(data []byte) error {
	if len(data) != 16 {
		return fmt.Errorf("invalid UUID (got %d bytes)", len(data))
	}
	copy(uuid[:], data)
	return nil
}

// Value implements driver.Valuer.
func (uuid UUID) Value() (any, error) {
	return uuid.String(), nil
}

// Scan implements sql.Scanner.
func (uuid *UUID) Scan(src any) error {
	switch v := src.(type) {
	case nil:
		return nil
	case string:
		return uuid.UnmarshalText([]byte(v))
	case []byte:
		if len(v) == 16 {
			return uuid.UnmarshalBinary(v)
		}
		return uuid.UnmarshalText(v)
	default:
		return fmt.Errorf("cannot convert %T to UUID", src)
	}
}

// newV4 returns a random (version 4) UUID.
func newV4() (UUID, error) {
	var uuid UUID
	if _, err := io.ReadFull(rand.Reader, uuid[:]); err != nil {
		return Nil, err
	}
	uuid[6] = (uuid[6] & 0x0f) | 0x40 // Version 4
	uuid[8] = (uuid[8] & 0x3f) | 0x80 // Variant is 10
	return uuid, nil
}

// epoch: 100-nanosecond intervals between 15 Oct 1582 and 1 Jan 1970.
const unixToUUIDEpoch = 122192928000000000

var (
	v1Mu          sync.Mutex
	clockSeq      uint16
	clockSeqErr   error
	clockSeqOnce  sync.Once
	nodeID        [6]byte
	nodeIDErr     error
	nodeOnce      sync.Once
	lastTimestamp uint64
)

// newV1 returns a UUID based on the current time and (if available) MAC
// address.
func newV1() (UUID, error) {
	nodeOnce.Do(func() {
		nodeID, nodeIDErr = getNodeID()
	})
	if nodeIDErr != nil {
		return Nil, nodeIDErr
	}
	clockSeqOnce.Do(func() {
		var b [2]byte
		if _, err := io.ReadFull(rand.Reader, b[:]); err != nil {
			clockSeqErr = err
			return
		}
		clockSeq = binary.BigEndian.Uint16(b[:])
	})
	if clockSeqErr != nil {
		return Nil, clockSeqErr
	}

	now := time.Now()
	ts := uint64(now.Unix())*10000000 + uint64(now.Nanosecond())/100 + unixToUUIDEpoch

	v1Mu.Lock()
	if ts <= lastTimestamp {
		clockSeq++
	}
	lastTimestamp = ts
	seq := clockSeq
	v1Mu.Unlock()

	var uuid UUID
	binary.BigEndian.PutUint32(uuid[0:], uint32(ts))
	binary.BigEndian.PutUint16(uuid[4:], uint16(ts>>32))
	binary.BigEndian.PutUint16(uuid[6:], uint16(ts>>48))
	uuid[6] = (uuid[6] & 0x0f) | 0x10 // Version 1
	binary.BigEndian.PutUint16(uuid[8:], seq)
	uuid[8] = (uuid[8] & 0x3f) | 0x80 // Variant is 10
	copy(uuid[10:], nodeID[:])
	return uuid, nil
}

// getNodeID returns the hardware address of the first network interface
// that has one, or a random 6-byte node id (with the multicast bit set) if
// no interface has a hardware address.
func getNodeID() ([6]byte, error) {
	var node [6]byte
	if ifaces, err := net.Interfaces(); err == nil {
		for _, iface := range ifaces {
			if len(iface.HardwareAddr) >= 6 {
				copy(node[:], iface.HardwareAddr)
				return node, nil
			}
		}
	}
	if _, err := io.ReadFull(rand.Reader, node[:]); err != nil {
		return node, err
	}
	// Set the multicast bit to distinguish from a real MAC address.
	node[0] |= 0x01
	return node, nil
}

package uuid

import (
	"bytes"
