)

func render(t *testing.T, tmpl string) (string, error) {
	t.Helper()
	fmap := template.FuncMap{"uuid": func() any { return NS() }}
	tt, err := template.New("<arg>").Option("missingkey=error").Funcs(fmap).Parse(tmpl)
	if err != nil {
		return "", err
	}
	var buf bytes.Buffer
	err = tt.Execute(&buf, map[string]any{"Env": map[string]string{}})
	return buf.String(), err
}

func mustRender(t *testing.T, tmpl string) string {
	t.Helper()
	out, err := render(t, tmpl)
	if err != nil {
		t.Fatalf("render(%q) failed: %v", tmpl, err)
	}
	return out
}

var canonicalRe = regexp.MustCompile(`^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$`)

func TestNil(t *testing.T) {
	out := mustRender(t, `{{ uuid.Nil }}`)
	if out != "00000000-0000-0000-0000-000000000000" {
		t.Errorf("uuid.Nil = %q, want nil UUID", out)
	}
}

func TestV4(t *testing.T) {
	seen := map[string]bool{}
	for i := 0; i < 10; i++ {
		out := mustRender(t, `{{ uuid.V4 }}`)
		if !canonicalRe.MatchString(out) {
			t.Fatalf("uuid.V4 = %q, not canonical form", out)
		}
		if out[14] != '4' {
			t.Errorf("uuid.V4 = %q, version nibble is %q, want '4'", out, out[14])
		}
		if !strings.ContainsRune("89ab", rune(out[19])) {
			t.Errorf("uuid.V4 = %q, variant nibble is %q, want one of 8,9,a,b", out, out[19])
		}
		if seen[out] {
			t.Errorf("uuid.V4 returned duplicate %q", out)
		}
		seen[out] = true
	}
}

func TestV1(t *testing.T) {
	seen := map[string]bool{}
	for i := 0; i < 10; i++ {
