func TestIsValid(t *testing.T) {
	tests := []struct {
		tmpl string
		want string
	}{
		{`{{ uuid.IsValid "totally invalid" }}`, "false"},
		{`{{ if uuid.IsValid "totally invalid" }}valid{{ else }}invalid{{ end }}`, "invalid"},
		{`{{ uuid.IsValid "12345678-90ab-cdef-fedc-ba9876543210" }}`, "true"},
		{`{{ uuid.IsValid "urn:uuid:12345678-90ab-cdef-fedc-ba9876543210" }}`, "true"},
		{`{{ uuid.IsValid "URN:UUID:12345678-90ab-cdef-fedc-ba9876543210" }}`, "true"},
		{`{{ uuid.IsValid "{12345678-90ab-cdef-fedc-ba9876543210}" }}`, "true"},
		{`{{ uuid.IsValid "1234567890abcdeffedcba9876543210" }}`, "true"},
		{`{{ uuid.IsValid "12345678-90ab-CDEF-FEDC-BA9876543210" }}`, "true"},
		{`{{ uuid.IsValid "" }}`, "false"},
		{`{{ uuid.IsValid "12345678-90ab-cdef-fedc-ba987654321" }}`, "false"},
		{`{{ uuid.IsValid "zzzzzzzz-90ab-cdef-fedc-ba9876543210" }}`, "false"},
		{`{{ uuid.IsValid "urn:uuid:12345678-90ab-cdef-fedc-ba98765432" }}`, "false"},
		// non-string inputs are coerced to strings first
		{`{{ uuid.IsValid 123 }}`, "false"},
		{`{{ uuid.IsValid true }}`, "false"},
		{`{{ uuid.IsValid 1.5 }}`, "false"},
