func TestParse(t *testing.T) {
	const canonical = "c232ab00-9414-11ec-b3c8-9f6bdeced846"
	// every accepted input form parses to the same canonical UUID
	forms := []string{
		`"c232ab00-9414-11ec-b3c8-9f6bdeced846"`,
		`"C232AB00-9414-11EC-B3C8-9F6BDECED846"`,
		`"urn:uuid:c232ab00-9414-11ec-b3c8-9f6bdeced846"`,
		`"URN:UUID:c232ab00-9414-11ec-b3c8-9f6bdeced846"`,
		`"uRn:uUuD:c232ab00-9414-11ec-b3c8-9f6bdeced846"`,
		`"{c232ab00-9414-11ec-b3c8-9f6bdeced846}"`,
		`"c232ab00941411ecb3c89f6bdeced846"`,
		`"C232AB00941411ECB3C89F6BDECED846"`,
	}
	for _, form := range forms {
		tmpl := `{{ (uuid.Parse ` + form + `).String }}`
		out := mustRender(t, tmpl)
		if out != canonical {
			t.Errorf("render(%q) = %q, want %q", tmpl, out, canonical)
		}
	}

	// printing a parsed UUID directly uses its String method
	out := mustRender(t, `{{ uuid.Parse "c232ab00-9414-11ec-b3c8-9f6bdeced846" }}`)
	if out != canonical {
		t.Errorf("direct print = %q, want %q", out, canonical)
	}

	// pipeline form
	out = mustRender(t, `{{ "c232ab00-9414-11ec-b3c8-9f6bdeced846" | uuid.Parse }}`)
	if out != canonical {
		t.Errorf("pipeline = %q, want %q", out, canonical)
	}

	// doc examples
	out = mustRender(t, `{{ $u := uuid.Parse uuid.V4 }}{{ $u.Version }}, {{ $u.Variant}}`)
	if out != "VERSION_4, RFC4122" {
		t.Errorf("doc example = %q, want %q", out, "VERSION_4, RFC4122")
	}
	out = mustRender(t, `{{ (uuid.Parse "000001f5-4470-21e9-9b00-72000877c7b0").Domain }}`)
	if out != "Person" {
		t.Errorf("doc example = %q, want %q", out, "Person")
	}
}

